INSERT INTO FDA_Product
SELECT product_ndc, NULLIF(generic_name,''), NULLIF(labeler_name,''),
       NULLIF(dosage_form,''), STR_TO_DATE(NULLIF(marketing_start_date,''),'%Y%m%d')
FROM JSON_TABLE(@ndc_json, '$[*]' COLUMNS (
 product_ndc VARCHAR(30) PATH '$.product_ndc',
 generic_name VARCHAR(255) PATH '$.generic_name',
 labeler_name VARCHAR(255) PATH '$.labeler_name',
 dosage_form VARCHAR(100) PATH '$.dosage_form',
 marketing_start_date VARCHAR(8) PATH '$.marketing_start_date'
