INSERT INTO FDA_Recall
SELECT recall_number, NULLIF(classification,''),
       STR_TO_DATE(NULLIF(recall_initiation_date,''),'%Y%m%d'),
       NULLIF(product_description,''), NULLIF(recalling_firm,''), NULLIF(reason_for_recall,'')
FROM JSON_TABLE(@recall_json, '$[*]' COLUMNS (
 recall_number VARCHAR(30) PATH '$.recall_number',
 classification VARCHAR(20) PATH '$.classification',
 recall_initiation_date VARCHAR(8) PATH '$.recall_initiation_date',
 product_description TEXT PATH '$.product_description',
 recalling_firm VARCHAR(255) PATH '$.recalling_firm',
 reason_for_recall TEXT PATH '$.reason_for_recall'
)) AS source_rows;
COMMIT;
SELECT 'FDA_Product' AS table_name, COUNT(*) AS row_count FROM FDA_Product
UNION ALL SELECT 'FDA_Recall', COUNT(*) FROM FDA_Recall;
